const results={links:[],failed:[],overlays:0};
async function link(node,dest,label){
  if(!node){results.failed.push(label+':node-missing');return;}
  try{node.reactions=[{trigger:{type:'CLICK'},action:{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:{type:'DISSOLVE',duration:0.3}}}];
    results.links.push(label);}
  catch(e){results.failed.push(label+':'+e.message);}
}
function navOverlay(frame,navText,dest,label){
  const fb=frame.absoluteBoundingBox,nb=navText.absoluteBoundingBox;
  const ov=figma.createFrame();ov.resize(Math.ceil(nb.width)+8,Math.ceil(nb.height)+8);
  ov.x=nb.x-fb.x-4;ov.y=nb.y-fb.y-4;ov.name='NavLink/'+label;ov.fills=[];ov.clipsContent=false;
  frame.appendChild(ov);
  ov.reactions=[{trigger:{type:'CLICK'},action:{type:'NODE',destinationId:dest,navigation:'NAVIGATE',transition:{type:'DISSOLVE',duration:0.3}}}];
  results.overlays++;results.links.push(label+'(overlay)');
}
