const frames={'01_Home':'17:44','02_Recipe':'19:435','03_Blog':'20:627','04_Blog_Post':'21:693','05_Contact':'23:803'};
const ACT=d=>[{type:'NODE',destinationId:d,navigation:'NAVIGATE',transition:{type:'DISSOLVE',duration:0.3,easing:{type:'EASE_IN_AND_OUT'}}}];
function findOne(n,name){if('children'in n){for(const c of n.children){if(c.name===name)return c;const r=findOne(c,name);if(r)return r;}}return null;}
const done=[],failed=[];
async function link(node,dest,label){if(!node){failed.push(label+':missing');return;}
  try{node.reactions=[{trigger:{type:'ON_CLICK'},actions:ACT(dest)}];done.push(label);}
  catch(e){failed.push(label+':'+e.message.slice(0,120));}}
for(const [fname,fid] of Object.entries(frames)){
  const frame=await figma.getNodeByIdAsync(fid);
  const header=frame.children.find(c=>c.type==='INSTANCE'&&c.name.indexOf('Site Header')===0);
  const selfMap={'01_Home':'Home','03_Blog':'Blog','05_Contact':'Contact'};
  const dests={Home:frames['01_Home'],Blog:frames['03_Blog'],Contact:frames['05_Contact']};
  for(const nm of ['Home','Blog','Contact']){
    if(selfMap[fname]===nm)continue;
    const t=header?findOne(header,'Nav/'+nm):null;
    await link(t,dests[nm],fname+'/nav '+nm);
  }
  if(fname==='01_Home'||fname==='04_Blog_Post'||fname==='05_Contact'){
    const card=frame.children.find(c=>c.name&&c.name.indexOf('Healthy Japanese Fri')>=0);
    await link(card,frames['02_Recipe'],fname+'/card fried-rice');
  }
  if(fname==='03_Blog'){
    const art=findOne(frame,'Article/Full Guide to Becoming a');
    await link(art,frames['04_Blog_Post'],fname+'/article');
  }
}
const counts={};
for(const [n,id] of Object.entries(frames)){const f=await figma.getNodeByIdAsync(id);let c=0;(function walk(node){if('reactions'in node&&node.reactions&&node.reactions.length)c++;if('children'in node)for(const ch of node.children)walk(ch);})(f);counts[n]=c;}
return JSON.stringify({done,failed,counts});

